import{_ as t,o as r,c as o,ae as a}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Kubernetes: exposure and probes","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1008684393/references/kubernetes.md","filePath":"adrs/1008684393/references/kubernetes.md"}'),s={name:"adrs/1008684393/references/kubernetes.md"};function d(n,e,c,i,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="kubernetes-exposure-and-probes" tabindex="-1">Kubernetes: exposure and probes <a class="header-anchor" href="#kubernetes-exposure-and-probes" aria-label="Permalink to &quot;Kubernetes: exposure and probes&quot;">​</a></h1><p>Verified against primary documentation and source on 2026-10-11.</p><h2 id="exposure" tabindex="-1">Exposure <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;Exposure&quot;">​</a></h2><p>Service types are <code>ClusterIP</code>, <code>NodePort</code>, <code>LoadBalancer</code> and <code>ExternalName</code> (<a href="https://kubernetes.io/docs/concepts/services-networking/service/" target="_blank" rel="noreferrer">Service</a>). Routing policy is split by where traffic starts: <code>externalTrafficPolicy</code> for traffic from outside the cluster and <code>internalTrafficPolicy</code> for traffic from inside it (<a href="https://kubernetes.io/docs/concepts/services-networking/service-traffic-policy/" target="_blank" rel="noreferrer">Service internal traffic policy</a>).</p><p>Gateway API names roles rather than exposure levels: the Infrastructure Provider owns <code>GatewayClass</code>, the Cluster Operator owns <code>Gateway</code> and its listeners, and the Application Developer attaches routes to them (<a href="https://gateway-api.sigs.k8s.io/docs/concepts/roles-and-personas/" target="_blank" rel="noreferrer">Roles and personas</a>).</p><h2 id="probes" tabindex="-1">Probes <a class="header-anchor" href="#probes" aria-label="Permalink to &quot;Probes&quot;">​</a></h2><p>The kubelet requests whatever path a probe names. An <code>httpGet</code> probe passes on any status from 200 to 399. The <code>grpc</code> probe, generally available since 1.27, calls <code>grpc.health.v1</code> <code>Check</code> with an optional service name over HTTP/2 without TLS (<a href="https://www.kubernetes.dev/resources/keps/2727/" target="_blank" rel="noreferrer">KEP-2727</a>). TLS needs the <code>GRPCContainerProbeTLS</code> feature gate, alpha and off by default since 1.37 (<a href="https://kubernetes.io/docs/concepts/workloads/pods/probes/" target="_blank" rel="noreferrer">Probes</a>).</p><p>The API server serves <code>/livez</code> and <code>/readyz</code>. <code>/healthz</code> has been deprecated since 1.16 because one endpoint could not say whether the server should be restarted or only taken out of rotation. Each check also has its own path, such as <code>/readyz/etcd</code>; <code>?verbose</code> lists them for people, and <code>?exclude=</code> skips one (<a href="https://kubernetes.io/docs/reference/using-api/health-checks/" target="_blank" rel="noreferrer">Kubernetes API health endpoints</a>).</p><p>kubeadm writes these probes for the control plane (<a href="https://github.com/kubernetes/kubernetes/blob/master/cmd/kubeadm/app/phases/controlplane/manifests.go" target="_blank" rel="noreferrer">controlplane/manifests.go</a>; <a href="https://github.com/kubernetes/kubernetes/blob/master/cmd/kubeadm/app/phases/etcd/local.go" target="_blank" rel="noreferrer">etcd/local.go</a>):</p><table tabindex="0"><thead><tr><th>Component</th><th>Startup</th><th>Liveness</th><th>Readiness</th></tr></thead><tbody><tr><td>kube-apiserver</td><td><code>/livez</code></td><td><code>/livez</code></td><td><code>/readyz</code></td></tr><tr><td>kube-scheduler</td><td><code>/livez</code></td><td><code>/livez</code></td><td><code>/readyz</code></td></tr><tr><td>kube-controller-manager</td><td><code>/healthz</code></td><td><code>/healthz</code></td><td>none</td></tr><tr><td>etcd</td><td><code>/readyz</code></td><td><code>/livez</code></td><td><code>/readyz</code></td></tr></tbody></table><p>No component has a startup endpoint. The startup probe reuses another endpoint with a longer budget, and liveness uses a higher <code>failureThreshold</code> than readiness.</p><p>Components also serve <code>/statusz</code> and <code>/flagz</code> for debugging (<a href="https://www.kubernetes.dev/resources/keps/4827/" target="_blank" rel="noreferrer">KEP-4827</a>; <a href="https://www.kubernetes.dev/resources/keps/4828/" target="_blank" rel="noreferrer">KEP-4828</a>).</p><h2 id="service-meshes" tabindex="-1">Service meshes <a class="header-anchor" href="#service-meshes" aria-label="Permalink to &quot;Service meshes&quot;">​</a></h2><p>Istio rewrites a Pod&#39;s probes to its sidecar agent, on port 15020, because the kubelet cannot present a mesh client certificate once mutual TLS is strict (<a href="https://istio.io/latest/docs/ops/configuration/mesh/app-health-check/" target="_blank" rel="noreferrer">Health checking of Istio services</a>).</p>',14)])])}const b=t(s,[["render",d]]);export{u as __pageData,b as default};
